import pandas as pd
import numpy as np
import json

# Example 1: pd.Series([np.uint64(2**63)], dtype=object).to_json()
try:
    result1 = pd.Series([np.uint64(2**63)], dtype=object).to_json()
    probe("pd.Series([np.uint64(2**63)], dtype=object).to_json()", result1)
except Exception as e:
    probe("pd.Series([np.uint64(2**63)], dtype=object).to_json()", "__error__: " + type(e).__name__ + ": " + str(e))

# Example 1 expected value
try:
    expected1 = '{"0":9223372036854775808}'
    probe("expected::pd.Series([np.uint64(2**63)], dtype=object).to_json()", expected1)
except Exception as e:
    probe("expected::pd.Series([np.uint64(2**63)], dtype=object).to_json()", "__error__: " + type(e).__name__ + ": " + str(e))

